package com.meetspace.repository; import com.meetspace.dto.RoomDtos.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class RoomRepository{private final JdbcTemplate j;public RoomRepository(JdbcTemplate j){this.j=j;} private Room row(java.sql.ResultSet r)throws java.sql.SQLException{UUID id=UUID.fromString(r.getString("id"));return new Room(id,r.getString("room_code"),r.getString("name"),r.getString("floor"),r.getInt("capacity"),r.getString("description"),facilities(id),r.getBoolean("is_active"));} public List<Room> all(){return j.query("select * from rooms order by floor,room_code",(r,n)->row(r));} public List<Room> active(){return j.query("select * from rooms where is_active=true order by floor,room_code",(r,n)->row(r));} public Optional<Room> byId(UUID id,boolean includeInactive){return j.query("select * from rooms where id=?"+(includeInactive?"":" and is_active=true"),(r,n)->row(r),id).stream().findFirst();} public UUID create(Save x){UUID id=UUID.randomUUID();j.update("insert into rooms(id,room_code,name,floor,capacity,description,is_active) values(?,?,?,?,?,?,true)",id,x.roomCode().trim(),x.name().trim(),x.floor().trim(),x.capacity(),x.description());replace(id,x.facilities());return id;} public boolean update(UUID id,Save x){int n=j.update("update rooms set room_code=?,name=?,floor=?,capacity=?,description=? where id=?",x.roomCode().trim(),x.name().trim(),x.floor().trim(),x.capacity(),x.description(),id);if(n>0)replace(id,x.facilities());return n>0;} public boolean deactivate(UUID id){return j.update("update rooms set is_active=false where id=? and is_active=true",id)>0;} private List<String> facilities(UUID id){return j.queryForList("select facility_name from room_facilities where room_id=? order by facility_name",String.class,id);} private void replace(UUID id,List<String> fs){j.update("delete from room_facilities where room_id=?",id);if(fs!=null)for(String f:new LinkedHashSet<>(fs.stream().map(String::trim).filter(s->!s.isBlank()).toList()))j.update("insert into room_facilities(room_id,facility_name) values(?,?)",id,f);}}